import { lazy, Suspense, useCallback, useEffect, useMemo, useState } from "react";

import { BaseerButton } from "./baseer-button";
import { BaseerCard } from "./baseer-card";
import { BaseerDialog } from "./baseer-dialog";
import { BaseerFilterBar } from "./baseer-filter-bar";
import { BaseerSearchSelect } from "./baseer-search-select";
import { BaseerSummaryMetric, BaseerSummaryMetricGrid } from "./baseer-summary-metric";
import { BaseerMoney } from "./baseer-money";
import { BaseerStatusBadge } from "./baseer-status-badge";
import { BaseerEmptyState, BaseerNotice, BaseerSectionHeader, BaseerWorkspace } from "./baseer-workspace";
import { DataTable, type DataTableColumn } from "./data-table";
import { activeSession, api, requestId, type ActiveSession } from "./daily-sales-client";
import { presentBaseerApiError } from "./baseer-api-error";
import { hrText } from "./hr-copy";
import { HrJobTitleSelect } from "./hr-job-titles";
import { cancelHrEmployeeAdministrativeDeduction, createHrEmployeeAdministrativeDeduction, deferHrEmployeeAdministrativeDeduction, deferHrEmployeeAdvance, getHrAdministrativeDeduction, getHrAdvance, getHrEmployee, issueHrEmployeeAdvance, listHrAdministrativeDeductions, listHrAdvances, listHrEmployees, settleHrEmployeeAdvanceDirectly, updateHrEmployee, type HrAdministrativeDeduction, type HrAdministrativeDeductionDetail, type HrAdvance, type HrAdvanceDetail, type HrDetail, type HrEmployee, type HrEmployeeStatus } from "./hr-client";

type Language = "ar" | "en";
type EmployeeForm = { employeeNumber: string; nameAr: string; nameEn: string; jobTitle: string; phone: string; email: string; workSchedule: string; hireDate: string; status: HrEmployeeStatus; terminatedAt: string; notes: string };
type AdvanceAllocation = { vaultId: string; amount: string; paymentMethod: "CASH" | "BANK_TRANSFER" | "BANK_CARD" | "BANK_PAYMENT" | "APP" | "" };
type AdvanceForm = { employeeId: string; businessDate: string; amount: string; notes: string; allocations: AdvanceAllocation[] };
type SettlementForm = { advanceId: string; businessDate: string; amount: string; deferRemainingUntil: string; notes: string; allocations: AdvanceAllocation[] };
type DeferralForm = { advanceId: string; businessDate: string; deferredUntil: string; reason: string };
type DeductionForm = { employeeId: string; businessDate: string; amount: string; description: string; plannedPayrollDate: string };
type DeductionDeferralForm = { deductionId: string; businessDate: string; deferredUntil: string; reason: string };
type DeductionCancellationForm = { deductionId: string; businessDate: string; reason: string };
type FinanceConfiguration = { suppliers: Array<{ id: string; nameAr: string; nameEn: string | null; status: "ACTIVE" | "ARCHIVED" }>; categories: Array<{ id: string; nameAr: string; nameEn: string; kind: "PURCHASE" | "EXPENSE" | "SALE"; status: "ACTIVE" | "ARCHIVED"; isPosting: boolean }>; vaults: Array<{ id: string; nameAr: string; nameEn: string; status: "ACTIVE" | "ARCHIVED"; isPaymentDestination: boolean; paymentMethod: AdvanceAllocation["paymentMethod"]; paymentMethods: Exclude<AdvanceAllocation["paymentMethod"], "">[] }> };

const today = () => new Date().toISOString().slice(0, 10);
const emptyEmployee = (): EmployeeForm => ({ employeeNumber: "", nameAr: "", nameEn: "", jobTitle: "", phone: "", email: "", workSchedule: "", hireDate: today(), status: "ACTIVE", terminatedAt: "", notes: "" });
const emptyAdvance = (employeeId = "", vaultId = "", paymentMethod: AdvanceAllocation["paymentMethod"] = ""): AdvanceForm => ({ employeeId, businessDate: today(), amount: "", notes: "", allocations: [{ vaultId, amount: "", paymentMethod }] });
const futureDate = (days: number) => { const date = new Date(); date.setDate(date.getDate() + days); return date.toISOString().slice(0, 10); };
const emptySettlement = (advanceId = "", amount = "", vaultId = "", paymentMethod: AdvanceAllocation["paymentMethod"] = ""): SettlementForm => ({ advanceId, businessDate: today(), amount, deferRemainingUntil: "", notes: "", allocations: [{ vaultId, amount, paymentMethod }] });
const emptyDeferral = (advanceId = ""): DeferralForm => ({ advanceId, businessDate: today(), deferredUntil: futureDate(30), reason: "" });
const emptyDeduction = (): DeductionForm => ({ employeeId: "", businessDate: today(), amount: "", description: "", plannedPayrollDate: "" });
const emptyDeductionDeferral = (deductionId = ""): DeductionDeferralForm => ({ deductionId, businessDate: today(), deferredUntil: futureDate(30), reason: "" });
const emptyDeductionCancellation = (deductionId = ""): DeductionCancellationForm => ({ deductionId, businessDate: today(), reason: "" });
const HrPayrollWorkspace = lazy(() => import("./hr-payroll-workspace").then((module) => ({ default: module.HrPayrollWorkspace })));
const HrLeaveWorkspace = lazy(() => import("./hr-leave-workspace").then((module) => ({ default: module.HrLeaveWorkspace })));
const HrServicesWorkspace = lazy(() => import("./hr-services-workspace").then((module) => ({ default: module.HrServicesWorkspace })));
const HrFinalSettlementWorkspace = lazy(() => import("./hr-final-settlement-workspace").then((module) => ({ default: module.HrFinalSettlementWorkspace })));
const HrSalaryToolsWorkspace = lazy(() => import("./hr-salary-tools-workspace").then((module) => ({ default: module.HrSalaryToolsWorkspace })));
const HrEmployeeProfileDialog = lazy(() => import("./hr-employee-profile-dialog").then((module) => ({ default: module.HrEmployeeProfileDialog })));
const HrCompensationAgreementDialog = lazy(() => import("./hr-compensation-agreement-dialog").then((module) => ({ default: module.HrCompensationAgreementDialog })));
const HrEmployeeOnboardingDialog = lazy(() => import("./hr-employee-onboarding-dialog").then((module) => ({ default: module.HrEmployeeOnboardingDialog })));
const DailySalesSignIn = lazy(() => import("./daily-sales-sign-in").then((module) => ({ default: module.DailySalesSignIn })));

export function HrWorkspace({ language, section }: { language: Language; section: number }) {
  if (section === 6) return <Suspense fallback={<BaseerCard>{language === "ar" ? "جارٍ تحميل نهاية الخدمة…" : "Loading end of service…"}</BaseerCard>}><HrFinalSettlementWorkspace language={language} /></Suspense>;
  if (section === 7) return <Suspense fallback={<BaseerCard>{language === "ar" ? "جارٍ تحميل أدوات الراتب…" : "Loading salary tools…"}</BaseerCard>}><HrSalaryToolsWorkspace language={language} /></Suspense>;
  return <HrWorkspaceCore language={language} section={section} />;
}

function HrWorkspaceCore({ language, section }: { language: Language; section: number }) {
  const text = hrText(language);
  const isAdvance = section === 4;
  const [session, setSession] = useState<ActiveSession | null>(activeSession());
  const [employees, setEmployees] = useState<HrEmployee[]>([]);
  const [advances, setAdvances] = useState<HrAdvance[]>([]);
  const [deductions, setDeductions] = useState<HrAdministrativeDeduction[]>([]);
  const [overview, setOverview] = useState({ activeEmployees: 0, employeesOnLeave: 0, openAdvances: 0, openAdministrativeDeductions: 0 });
  const [nextEmployeeCursor, setNextEmployeeCursor] = useState<string | null>(null);
  const [nextAdvanceCursor, setNextAdvanceCursor] = useState<string | null>(null);
  const [nextDeductionCursor, setNextDeductionCursor] = useState<string | null>(null);
  const [configuration, setConfiguration] = useState<FinanceConfiguration | null>(null);
  const [search, setSearch] = useState("");
  const [employeeFilter, setEmployeeFilter] = useState("");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [detail, setDetail] = useState<HrDetail | null>(null);
  const [compensationTarget, setCompensationTarget] = useState<{ employee: HrEmployee; profile: HrDetail["compensation"] } | null>(null);
  const [advanceDetail, setAdvanceDetail] = useState<HrAdvanceDetail | null>(null);
  const [deductionDetail, setDeductionDetail] = useState<HrAdministrativeDeductionDetail | null>(null);
  const [employeeOpen, setEmployeeOpen] = useState(false);
  const [onboardingOpen, setOnboardingOpen] = useState(false);
  const [editingEmployeeId, setEditingEmployeeId] = useState<string | null>(null);
  const [advanceOpen, setAdvanceOpen] = useState(false);
  const [settlementOpen, setSettlementOpen] = useState(false);
  const [deferralOpen, setDeferralOpen] = useState(false);
  const [deductionOpen, setDeductionOpen] = useState(false);
  const [deductionDeferralOpen, setDeductionDeferralOpen] = useState(false);
  const [deductionCancellationOpen, setDeductionCancellationOpen] = useState(false);
  const [employeeForm, setEmployeeForm] = useState<EmployeeForm>(emptyEmployee());
  const [advanceForm, setAdvanceForm] = useState<AdvanceForm>(emptyAdvance());
  const [settlementForm, setSettlementForm] = useState<SettlementForm>(emptySettlement());
  const [deferralForm, setDeferralForm] = useState<DeferralForm>(emptyDeferral());
  const [deductionForm, setDeductionForm] = useState<DeductionForm>(emptyDeduction());
  const [deductionDeferralForm, setDeductionDeferralForm] = useState<DeductionDeferralForm>(emptyDeductionDeferral());
  const [deductionCancellationForm, setDeductionCancellationForm] = useState<DeductionCancellationForm>(emptyDeductionCancellation());

  const load = useCallback(async () => {
    const current = activeSession(); setSession(current); if (!current) { setLoading(false); return; }
    setLoading(true);
    try { const [employeeReceipt, advanceReceipt, deductionReceipt] = await Promise.all([listHrEmployees(current), listHrAdvances(current, { employeeId: employeeFilter || undefined }), listHrAdministrativeDeductions(current, { employeeId: employeeFilter || undefined })]); setEmployees(employeeReceipt.employees); setOverview(employeeReceipt.summary); setAdvances(advanceReceipt.advances); setDeductions(deductionReceipt.deductions); setNextEmployeeCursor(employeeReceipt.nextCursor); setNextAdvanceCursor(advanceReceipt.nextCursor); setNextDeductionCursor(deductionReceipt.nextCursor); }
    catch (error) { setMessage(presentBaseerApiError(error, language, text.loading)); }
    finally { setLoading(false); }
  }, [employeeFilter, language, text.loading]);
  useEffect(() => { void load(); }, [load]);
  const loadConfiguration = useCallback(async () => { const current = activeSession(); if (!current) return null; const next = await api<FinanceConfiguration>(current, "/finance/configuration"); setConfiguration(next); return next; }, []);
  const searchEmployeeOptions = useCallback(async (query: string) => {
    const current = activeSession(); if (!current) return [];
    const receipt = await listHrEmployees(current, { search: query.trim() || undefined, pageSize: 50 });
    return receipt.employees.filter((employee) => employee.status === "ACTIVE" || employee.status === "ON_LEAVE").map((employee) => ({ id: employee.id, label: `${employee.employeeNumber} · ${language === "ar" ? employee.nameAr : employee.nameEn ?? employee.nameAr}` }));
  }, [language]);
  const refreshDetail = async (employeeId: string) => { const current = activeSession(); if (current) setDetail(await getHrEmployee(current, employeeId)); };
  const loadMoreMovements = async () => {
    const current = activeSession();
    if (!current || !detail?.nextMovementCursor) return;
    try {
      const next = await getHrEmployee(current, detail.employee.id, detail.nextMovementCursor);
      setDetail((currentDetail) => currentDetail ? { ...next, movements: [...currentDetail.movements, ...next.movements] } : currentDetail);
    } catch (error) {
      setMessage(presentBaseerApiError(error, language, text.financialRecord));
    }
  };
  const loadMoreRegister = async (kind: "employees" | "advances" | "deductions") => {
    const current = activeSession();
    if (!current) return;
    try {
      if (kind === "employees" && nextEmployeeCursor) {
        const receipt = await listHrEmployees(current, { cursor: nextEmployeeCursor });
        setEmployees((rows) => [...rows, ...receipt.employees]); setNextEmployeeCursor(receipt.nextCursor);
      } else if (kind === "advances" && nextAdvanceCursor) {
        const receipt = await listHrAdvances(current, { employeeId: employeeFilter || undefined, cursor: nextAdvanceCursor });
        setAdvances((rows) => [...rows, ...receipt.advances]); setNextAdvanceCursor(receipt.nextCursor);
      } else if (kind === "deductions" && nextDeductionCursor) {
        const receipt = await listHrAdministrativeDeductions(current, { employeeId: employeeFilter || undefined, cursor: nextDeductionCursor });
        setDeductions((rows) => [...rows, ...receipt.deductions]); setNextDeductionCursor(receipt.nextCursor);
      }
    } catch (error) {
      setMessage(presentBaseerApiError(error, language, text.loadMore));
    }
  };
  const showDetail = async (employee: HrEmployee) => { try { await refreshDetail(employee.id); } catch (error) { setMessage(presentBaseerApiError(error, language, text.employeeFile)); } };
  const showAdvanceDetail = async (advance: HrAdvance) => { const current = activeSession(); if (!current) return; try { setAdvanceDetail(await getHrAdvance(current, advance.id)); } catch (error) { setMessage(presentBaseerApiError(error, language, text.advances)); } };
  const showDeductionDetail = async (deduction: HrAdministrativeDeduction) => { const current = activeSession(); if (!current) return; try { setDeductionDetail(await getHrAdministrativeDeduction(current, deduction.id)); } catch (error) { setMessage(presentBaseerApiError(error, language, text.administrativeDeductions)); } };
  const openEmployeeEdit = (employee: HrEmployee) => { setEditingEmployeeId(employee.id); setEmployeeForm({ employeeNumber: employee.employeeNumber, nameAr: employee.nameAr, nameEn: employee.nameEn ?? "", jobTitle: employee.jobTitle ?? "", phone: employee.phone ?? "", email: employee.email ?? "", workSchedule: employee.workSchedule ?? "", hireDate: employee.hireDate, status: employee.status, terminatedAt: employee.terminatedAt ?? "", notes: employee.notes ?? "" }); setEmployeeOpen(true); };
  const saveEmployee = async (event: React.FormEvent) => { event.preventDefault(); const current = activeSession(); if (!current || saving || !editingEmployeeId) return; setSaving(true); try { await updateHrEmployee(current, { employeeId: editingEmployeeId, nameAr: employeeForm.nameAr, nameEn: employeeForm.nameEn || null, jobTitle: employeeForm.jobTitle || null, phone: employeeForm.phone || null, email: employeeForm.email || null, workSchedule: employeeForm.workSchedule || null, status: employeeForm.status, terminatedAt: employeeForm.status === "TERMINATED" ? employeeForm.terminatedAt : null, notes: employeeForm.notes || null, idempotencyKey: requestId() }); const updatedId = editingEmployeeId; setEmployeeOpen(false); setEditingEmployeeId(null); setEmployeeForm(emptyEmployee()); setMessage(text.employeeUpdated); await load(); if (detail?.employee.id === updatedId) await refreshDetail(updatedId); } catch (error) { setMessage(presentBaseerApiError(error, language, text.employeeUpdated)); } finally { setSaving(false); } };
  const openAdvance = async () => { try { const next = configuration ?? await loadConfiguration(); const firstVault = next?.vaults.find((item) => item.status === "ACTIVE" && item.isPaymentDestination); setAdvanceForm(emptyAdvance("", firstVault?.id ?? "", firstVault?.paymentMethod ?? "")); setAdvanceOpen(true); } catch (error) { setMessage(presentBaseerApiError(error, language, text.addAdvance)); } };
  const saveAdvance = async (event: React.FormEvent) => { event.preventDefault(); const current = activeSession(); if (!current || saving) return; setSaving(true); try { await issueHrEmployeeAdvance(current, { employeeId: advanceForm.employeeId, businessDate: advanceForm.businessDate, amount: advanceForm.amount, notes: advanceForm.notes || undefined, allocations: advanceForm.allocations.map((item) => ({ vaultId: item.vaultId, amount: item.amount, paymentMethod: item.paymentMethod || undefined })), idempotencyKey: requestId() }); setAdvanceOpen(false); setMessage(text.advanceSaved); await load(); if (detail?.employee.id === advanceForm.employeeId) await refreshDetail(advanceForm.employeeId); } catch (error) { setMessage(presentBaseerApiError(error, language, text.addAdvance)); } finally { setSaving(false); } };
  const openSettlement = async (advance: HrAdvance) => { try { const next = configuration ?? await loadConfiguration(); const firstVault = next?.vaults.find((item) => item.status === "ACTIVE" && item.isPaymentDestination); setSettlementForm(emptySettlement(advance.id, advance.remainingAmount, firstVault?.id ?? "", firstVault?.paymentMethod ?? "")); setSettlementOpen(true); } catch (error) { setMessage(presentBaseerApiError(error, language, text.settleAdvance)); } };
  const saveSettlement = async (event: React.FormEvent) => { event.preventDefault(); const current = activeSession(); if (!current || saving) return; setSaving(true); try { await settleHrEmployeeAdvanceDirectly(current, { advanceId: settlementForm.advanceId, businessDate: settlementForm.businessDate, amount: settlementForm.amount, deferRemainingUntil: settlementForm.deferRemainingUntil || undefined, notes: settlementForm.notes || undefined, allocations: settlementForm.allocations.map((item) => ({ vaultId: item.vaultId, amount: item.amount, paymentMethod: item.paymentMethod || undefined })), idempotencyKey: requestId() }); setSettlementOpen(false); setMessage(text.settlementSaved); await load(); } catch (error) { setMessage(presentBaseerApiError(error, language, text.settleAdvance)); } finally { setSaving(false); } };
  const openDeferral = (advance: HrAdvance) => { setDeferralForm({ ...emptyDeferral(advance.id), deferredUntil: advance.nextSettlementDate ?? futureDate(30) }); setDeferralOpen(true); };
  const saveDeferral = async (event: React.FormEvent) => { event.preventDefault(); const current = activeSession(); if (!current || saving) return; setSaving(true); try { await deferHrEmployeeAdvance(current, { ...deferralForm, idempotencyKey: requestId() }); setDeferralOpen(false); setMessage(text.deferralSaved); await load(); } catch (error) { setMessage(presentBaseerApiError(error, language, text.deferAdvance)); } finally { setSaving(false); } };
  const saveDeduction = async (event: React.FormEvent) => { event.preventDefault(); const current = activeSession(); if (!current || saving) return; setSaving(true); try { await createHrEmployeeAdministrativeDeduction(current, { ...deductionForm, plannedPayrollDate: deductionForm.plannedPayrollDate || undefined, idempotencyKey: requestId() }); setDeductionOpen(false); setDeductionForm(emptyDeduction()); setMessage(text.deductionSaved); await load(); } catch (error) { setMessage(presentBaseerApiError(error, language, text.addAdministrativeDeduction)); } finally { setSaving(false); } };
  const openDeductionDeferral = (deduction: HrAdministrativeDeduction) => { setDeductionDeferralForm({ ...emptyDeductionDeferral(deduction.id), deferredUntil: deduction.plannedPayrollDate ?? futureDate(30) }); setDeductionDeferralOpen(true); };
  const saveDeductionDeferral = async (event: React.FormEvent) => { event.preventDefault(); const current = activeSession(); if (!current || saving) return; setSaving(true); try { await deferHrEmployeeAdministrativeDeduction(current, { ...deductionDeferralForm, idempotencyKey: requestId() }); setDeductionDeferralOpen(false); setMessage(text.deductionDeferred); await load(); } catch (error) { setMessage(presentBaseerApiError(error, language, text.deferDeduction)); } finally { setSaving(false); } };
  const openDeductionCancellation = (deduction: HrAdministrativeDeduction) => { setDeductionCancellationForm(emptyDeductionCancellation(deduction.id)); setDeductionCancellationOpen(true); };
  const saveDeductionCancellation = async (event: React.FormEvent) => { event.preventDefault(); const current = activeSession(); if (!current || saving) return; setSaving(true); try { await cancelHrEmployeeAdministrativeDeduction(current, { ...deductionCancellationForm, idempotencyKey: requestId() }); setDeductionCancellationOpen(false); setMessage(text.deductionCancelled); await load(); } catch (error) { setMessage(presentBaseerApiError(error, language, text.cancelDeduction)); } finally { setSaving(false); } };

  const visibleEmployees = useMemo(() => filter(employees, search, (item) => [item.employeeNumber, item.nameAr, item.nameEn, item.jobTitle]), [employees, search]);
  const visibleAdvances = useMemo(() => filter(advances.filter((item) => !employeeFilter || item.employeeId === employeeFilter), search, (item) => [item.advanceNumber, item.employeeNameAr, item.employeeNameEn, item.notes]), [advances, employeeFilter, search]);
  const visibleDeductions = useMemo(() => filter(deductions.filter((item) => !employeeFilter || item.employeeId === employeeFilter), search, (item) => [item.deductionNumber, item.employeeNameAr, item.employeeNameEn, item.description, item.status]), [deductions, employeeFilter, search]);
  const statusLabel = (status: HrEmployeeStatus) => ({ ACTIVE: text.active, ON_LEAVE: text.onLeave, TERMINATED: text.terminated, ARCHIVED: text.archived })[status];
  const sectionTitle = [text.overview, text.employees, language === "ar" ? "الإجازات والعودة" : "Leave & return", language === "ar" ? "الرواتب" : "Payroll", language === "ar" ? "السلف والخصومات" : "Advances & deductions", text.services][section] ?? text.title;
  const employeeColumns: readonly DataTableColumn<HrEmployee>[] = [
    { id: "number", header: text.employeeNumber, cell: (row) => row.employeeNumber, width: "9rem", sort: (row) => row.employeeNumber },
    { id: "name", header: text.employeeName, cell: (row) => <button type="button" className="baseer-button baseer-button--secondary" onClick={() => void showDetail(row)}>{language === "ar" ? row.nameAr : row.nameEn ?? row.nameAr}</button>, sort: (row) => language === "ar" ? row.nameAr : row.nameEn ?? row.nameAr },
    { id: "job", header: text.jobTitle, cell: (row) => row.jobTitle ?? "—", sort: (row) => row.jobTitle },
    { id: "hire", header: text.hireDate, cell: (row) => row.hireDate, width: "9rem", sort: (row) => row.hireDate },
    { id: "status", header: text.status, cell: (row) => <BaseerStatusBadge tone={row.status === "ACTIVE" ? "success" : row.status === "ON_LEAVE" ? "warning" : "neutral"}>{statusLabel(row.status)}</BaseerStatusBadge>, width: "8rem", sort: (row) => row.status },
  ];
  const advanceColumns: readonly DataTableColumn<HrAdvance>[] = [
    { id: "number", header: text.advanceNumber, cell: (row) => <BaseerButton type="button" variant="quiet" onClick={() => void showAdvanceDetail(row)}>{row.advanceNumber}</BaseerButton>, width: "13rem", sort: (row) => row.advanceNumber },
    { id: "employee", header: text.employeeName, cell: (row) => language === "ar" ? row.employeeNameAr : row.employeeNameEn ?? row.employeeNameAr, sort: (row) => language === "ar" ? row.employeeNameAr : row.employeeNameEn ?? row.employeeNameAr },
    { id: "date", header: text.date, cell: (row) => row.businessDate, width: "9rem", sort: (row) => row.businessDate },
    { id: "original", header: text.originalAmount, cell: (row) => <BaseerMoney value={row.originalAmount} language={language} />, align: "end", numeric: true, width: "9rem", sort: (row) => row.originalAmount },
    { id: "remaining", header: text.remainingAmount, cell: (row) => <BaseerMoney value={row.remainingAmount} language={language} />, align: "end", numeric: true, width: "10rem", sort: (row) => row.remainingAmount },
    { id: "next", header: text.nextSettlementDate, cell: (row) => row.nextSettlementDate ?? "—", width: "11rem", sort: (row) => row.nextSettlementDate },
    { id: "settle", header: text.settleAdvance, cell: (row) => row.remainingAmount !== "0.0000" ? <BaseerButton type="button" variant="secondary" onClick={() => void openSettlement(row)}>{text.settleAdvance}</BaseerButton> : "—", width: "11rem" },
    { id: "defer", header: text.deferAdvance, cell: (row) => row.remainingAmount !== "0.0000" ? <BaseerButton type="button" variant="quiet" onClick={() => openDeferral(row)}>{text.deferAdvance}</BaseerButton> : "—", width: "11rem" },
  ];
  const deductionColumns: readonly DataTableColumn<HrAdministrativeDeduction>[] = [
    { id: "number", header: text.deductionNumber, cell: (row) => <BaseerButton type="button" variant="quiet" onClick={() => void showDeductionDetail(row)}>{row.deductionNumber}</BaseerButton>, width: "13rem", sort: (row) => row.deductionNumber },
    { id: "employee", header: text.employeeName, cell: (row) => language === "ar" ? row.employeeNameAr : row.employeeNameEn ?? row.employeeNameAr, sort: (row) => language === "ar" ? row.employeeNameAr : row.employeeNameEn ?? row.employeeNameAr },
    { id: "description", header: text.deductionDescription, cell: (row) => row.description, sort: (row) => row.description },
    { id: "amount", header: text.originalAmount, cell: (row) => <BaseerMoney value={row.originalAmount} language={language} />, align: "end", numeric: true, width: "9rem", sort: (row) => row.originalAmount },
    { id: "remaining", header: text.remainingAmount, cell: (row) => <BaseerMoney value={row.remainingAmount} language={language} />, align: "end", numeric: true, width: "10rem", sort: (row) => row.remainingAmount },
    { id: "date", header: text.plannedPayrollDate, cell: (row) => row.plannedPayrollDate ?? "—", width: "11rem", sort: (row) => row.plannedPayrollDate },
    { id: "status", header: text.status, cell: (row) => <BaseerStatusBadge tone={row.status === "APPLIED" ? "success" : row.status === "CANCELLED" ? "neutral" : row.status === "DEFERRED" ? "warning" : "info"}>{deductionStatusLabel(text, row.status)}</BaseerStatusBadge>, width: "9rem", sort: (row) => row.status },
    { id: "defer", header: text.deferDeduction, cell: (row) => deductionIsOpen(row) ? <BaseerButton type="button" variant="quiet" onClick={() => openDeductionDeferral(row)}>{text.deferDeduction}</BaseerButton> : "—", width: "11rem" },
    { id: "cancel", header: text.cancelDeduction, cell: (row) => deductionIsOpen(row) ? <BaseerButton type="button" variant="quiet" onClick={() => openDeductionCancellation(row)}>{text.cancelDeduction}</BaseerButton> : "—", width: "11rem" },
  ];
  const activeEmployees = employees.filter((item) => item.status === "ACTIVE" || item.status === "ON_LEAVE");
  const activeVaults = configuration?.vaults.filter((item) => item.status === "ACTIVE" && item.isPaymentDestination) ?? [];
  const createEmployeeAction = <BaseerButton type="button" onClick={() => setOnboardingOpen(true)}>{text.addEmployee}</BaseerButton>;

  if (!session) return <Suspense fallback={<BaseerCard>{text.loading}</BaseerCard>}><DailySalesSignIn language={language} /></Suspense>;
  if (section === 3) return <Suspense fallback={<BaseerCard>{language === "ar" ? "جارٍ تحميل مسير الرواتب…" : "Loading payroll…"}</BaseerCard>}><HrPayrollWorkspace language={language} /></Suspense>;
  if (section === 2) return <Suspense fallback={<BaseerCard>{language === "ar" ? "جارٍ تحميل الإجازات والعودة…" : "Loading leave & return…"}</BaseerCard>}><HrLeaveWorkspace language={language} /></Suspense>;
  if (section === 5) return <Suspense fallback={<BaseerCard>{language === "ar" ? "جارٍ تحميل خدمات الموظفين…" : "Loading employee services…"}</BaseerCard>}><HrServicesWorkspace language={language} /></Suspense>;
  return <BaseerWorkspace aria-label={text.title}>
    <BaseerSectionHeader eyebrow={section === 0 ? (language === "ar" ? "مركز عمل الموارد البشرية" : "HR operations hub") : undefined} title={sectionTitle} description={section === 0 ? (language === "ar" ? "صورة تشغيلية سريعة للموظفين والاستحقاقات المفتوحة قبل الانتقال إلى السجل المناسب." : "A focused operational snapshot before moving into the relevant register.") : section === 1 ? (language === "ar" ? "أنشئ الموظف واتفاقه المالي الأول في نموذج واحد واضح، ثم راجع تفاصيله من ملفه المتكامل." : "Create the employee and first compensation agreement in one clear form, then review everything from the complete employee file.") : undefined} actions={section === 1 ? <BaseerButton type="button" variant="primary" onClick={() => setOnboardingOpen(true)}>{text.addEmployee}</BaseerButton> : isAdvance ? <><BaseerButton type="button" variant="primary" onClick={() => void openAdvance()}>{text.addAdvance}</BaseerButton><BaseerButton type="button" variant="secondary" onClick={() => { setDeductionForm(emptyDeduction()); setDeductionOpen(true); }}>{text.addAdministrativeDeduction}</BaseerButton></> : undefined} />
    {message ? <BaseerNotice tone="success">{message}</BaseerNotice> : null}
    {section === 0 ? (
      <>
        <BaseerSummaryMetricGrid><BaseerSummaryMetric label={text.active} value={String(overview.activeEmployees)} /><BaseerSummaryMetric label={text.onLeave} value={String(overview.employeesOnLeave)} /><BaseerSummaryMetric label={text.advances} value={String(overview.openAdvances)} /><BaseerSummaryMetric label={text.administrativeDeductions} value={String(overview.openAdministrativeDeductions)} /></BaseerSummaryMetricGrid>
        <BaseerNotice title={language === "ar" ? "مبدأ العمل" : "Operating principle"}>{language === "ar" ? "ملف الموظف هو نقطة الانطلاق: منه تُدار بياناته واتفاقه ووثائقه وحركاته، بينما تبقى السلف والخصومات مسارات مستقلة وموثقة." : "The employee file is the operational starting point for identity, agreement, documents, and movements. Advances and deductions remain separate, governed records."}</BaseerNotice>
      </>
    ) : (
      <>
        <BaseerFilterBar language={language} search={search} searchLabel={sectionTitle} searchPlaceholder={sectionTitle} onSearchChange={setSearch} controls={isAdvance ? <BaseerSearchSelect label={text.selectEmployee} value={employeeFilter} placeholder={text.selectEmployee} options={activeEmployees.map((item) => ({ id: item.id, label: `${item.employeeNumber} · ${language === "ar" ? item.nameAr : (item.nameEn ?? item.nameAr)}` }))} remoteSearch={searchEmployeeOptions} onChange={setEmployeeFilter} /> : undefined} appliedFilters={[...(search ? [{ id: "q", label: search, onRemove: () => setSearch("") }] : []), ...(employeeFilter ? [{ id: "employee", label: activeEmployees.find((item) => item.id === employeeFilter)?.nameAr ?? employeeFilter, onRemove: () => setEmployeeFilter("") }] : [])]} onClear={() => { setSearch(""); setEmployeeFilter(""); }} />
        {loading ? <BaseerCard><p>{text.loading}</p></BaseerCard> : isAdvance ? (
          <>
            <BaseerNotice tone="info">{text.advancePolicy}<br />{text.advancePending}</BaseerNotice>
            {visibleAdvances.length ? <DataTable ariaLabel={text.advances} caption={text.advances} columns={advanceColumns} rows={visibleAdvances} rowKey={(row) => row.id} /> : <BaseerEmptyState title={language === "ar" ? "لا توجد سلف مسجلة" : "No advances recorded"} />}
            {visibleDeductions.length ? <DataTable ariaLabel={text.administrativeDeductions} caption={text.administrativeDeductions} columns={deductionColumns} rows={visibleDeductions} rowKey={(row) => row.id} /> : <BaseerEmptyState title={language === "ar" ? "لا توجد خصومات إدارية" : "No administrative deductions"} />}
          </>
        ) : visibleEmployees.length ? <DataTable ariaLabel={sectionTitle} caption={sectionTitle} columns={employeeColumns} rows={visibleEmployees} rowKey={(row) => row.id} /> : <BaseerEmptyState title={text.noEmployees} action={createEmployeeAction} />}
      </>
    )}
    {!loading && section === 1 && nextEmployeeCursor ? <BaseerButton type="button" variant="secondary" onClick={() => void loadMoreRegister("employees")}>{text.loadMore}</BaseerButton> : null}
    {!loading && isAdvance && (nextAdvanceCursor || nextDeductionCursor) ? <BaseerButton type="button" variant="secondary" onClick={() => { if (nextAdvanceCursor) void loadMoreRegister("advances"); if (nextDeductionCursor) void loadMoreRegister("deductions"); }}>{text.loadMore}</BaseerButton> : null}

    {onboardingOpen ? <Suspense fallback={null}><HrEmployeeOnboardingDialog open language={language} onClose={() => setOnboardingOpen(false)} onSaved={async () => { setMessage(text.employeeSaved); await load(); }} onError={setMessage} /></Suspense> : null}
    <BaseerDialog open={employeeOpen} title={text.editEmployee} language={language} busy={saving} onClose={() => { setEmployeeOpen(false); setEditingEmployeeId(null); }} footer={<><BaseerButton type="button" variant="secondary" disabled={saving} onClick={() => { setEmployeeOpen(false); setEditingEmployeeId(null); }}>{text.cancel}</BaseerButton><BaseerButton type="submit" form="hr-employee-form" variant="primary" disabled={saving}>{text.save}</BaseerButton></>}>
      <form id="hr-employee-form" className="administration-form" onSubmit={(event) => void saveEmployee(event)}>
        {editingEmployeeId ? <label>{text.employeeNumber}<input readOnly value={employeeForm.employeeNumber} /></label> : <BaseerNotice tone="info">{language === "ar" ? "يُنشئ النظام رقم الموظف تلقائياً بالتسلسل: EMP-001، ثم EMP-002…" : "The system assigns the employee number automatically in sequence: EMP-001, then EMP-002…"}</BaseerNotice>}
        <label>{text.employeeName}<input required value={employeeForm.nameAr} onChange={(event) => setEmployeeForm((value) => ({ ...value, nameAr: event.target.value }))} /></label>
        <label>{text.englishName}<input value={employeeForm.nameEn} onChange={(event) => setEmployeeForm((value) => ({ ...value, nameEn: event.target.value }))} /></label>
        <label>{text.hireDate}<input required readOnly={Boolean(editingEmployeeId)} type="date" value={employeeForm.hireDate} max={today()} onChange={(event) => setEmployeeForm((value) => ({ ...value, hireDate: event.target.value }))} /></label>
        <label>{text.jobTitle}<HrJobTitleSelect id="hr-edit-job-titles" language={language} value={employeeForm.jobTitle} onChange={(jobTitle) => setEmployeeForm((value) => ({ ...value, jobTitle }))} /></label>
        <label>{text.phone}<input value={employeeForm.phone} onChange={(event) => setEmployeeForm((value) => ({ ...value, phone: event.target.value }))} /></label>
        <label>{text.email}<input type="email" value={employeeForm.email} onChange={(event) => setEmployeeForm((value) => ({ ...value, email: event.target.value }))} /></label>
        <label>{language === "ar" ? "نظام العمل" : "Work schedule"}<input value={employeeForm.workSchedule} onChange={(event) => setEmployeeForm((value) => ({ ...value, workSchedule: event.target.value }))} /></label>
        {editingEmployeeId ? <><label>{text.status}<BaseerSearchSelect searchable={false} required label={text.status} value={employeeForm.status} placeholder={text.status} options={(["ACTIVE", "ON_LEAVE", "TERMINATED", "ARCHIVED"] as const).map((status) => ({ id: status, label: statusLabel(status) }))} onChange={(status) => setEmployeeForm((value) => ({ ...value, status: status as HrEmployeeStatus, terminatedAt: status === "TERMINATED" ? value.terminatedAt : "" }))} /></label>{employeeForm.status === "TERMINATED" ? <label>{text.terminationDate}<input required type="date" min={employeeForm.hireDate} max={today()} value={employeeForm.terminatedAt} onChange={(event) => setEmployeeForm((value) => ({ ...value, terminatedAt: event.target.value }))} /></label> : null}</> : null}
        <label>{text.notes}<textarea value={employeeForm.notes} onChange={(event) => setEmployeeForm((value) => ({ ...value, notes: event.target.value }))} /></label>
      </form>
    </BaseerDialog>
    {detail ? <Suspense fallback={null}><HrEmployeeProfileDialog detail={detail} language={language} onClose={() => setDetail(null)} onEdit={() => { openEmployeeEdit(detail.employee); setDetail(null); }} onManageCompensation={() => { setCompensationTarget({ employee: detail.employee, profile: detail.compensation }); setDetail(null); }} onLoadMoreMovements={loadMoreMovements} onError={setMessage} onChanged={async () => { await load(); await refreshDetail(detail.employee.id); }} /></Suspense> : null}
    {compensationTarget ? <Suspense fallback={null}><HrCompensationAgreementDialog open language={language} employees={employees} fixedEmployeeId={compensationTarget.employee.id} profile={compensationTarget.profile} onClose={() => setCompensationTarget(null)} onSaved={async () => { setMessage(language === "ar" ? "تم حفظ اتفاق الراتب؛ ستُستخدم النسخة من شهر سريانها." : "Compensation agreement saved; it will be used from its effective month."); await load(); }} onError={setMessage} /></Suspense> : null}
    <BaseerDialog open={advanceDetail !== null} title={advanceDetail?.advance.advanceNumber ?? text.advances} language={language} onClose={() => setAdvanceDetail(null)} footer={<BaseerButton type="button" variant="secondary" onClick={() => setAdvanceDetail(null)}>{text.cancel}</BaseerButton>}>{advanceDetail ? <div className="administration-list"><article><strong>{language === "ar" ? advanceDetail.advance.employeeNameAr : advanceDetail.advance.employeeNameEn ?? advanceDetail.advance.employeeNameAr}</strong><span>{text.originalAmount}: {advanceDetail.advance.originalAmount}</span><span>{text.remainingAmount}: {advanceDetail.advance.remainingAmount}</span><span>{text.status}: {advanceDetail.advance.status}</span></article><article><strong>{text.settleAdvance}</strong>{advanceDetail.settlements.length ? advanceDetail.settlements.map((item) => <span key={item.id}>{item.businessDate} · {item.amount} · {item.source === "PAYROLL" ? text.payrollPayment : text.settleAdvance} · {item.sourceReference ?? "—"}</span>) : <span>—</span>}</article><article><strong>{text.deferAdvance}</strong>{advanceDetail.deferrals.length ? advanceDetail.deferrals.map((item) => <span key={item.id}>{item.businessDate} · {item.deferredUntil} · {item.reason}</span>) : <span>—</span>}</article></div> : null}</BaseerDialog>
    <BaseerDialog open={deductionDetail !== null} title={deductionDetail?.deduction.deductionNumber ?? text.administrativeDeductions} language={language} onClose={() => setDeductionDetail(null)} footer={<BaseerButton type="button" variant="secondary" onClick={() => setDeductionDetail(null)}>{text.cancel}</BaseerButton>}>{deductionDetail ? <div className="administration-list"><article><strong>{language === "ar" ? deductionDetail.deduction.employeeNameAr : deductionDetail.deduction.employeeNameEn ?? deductionDetail.deduction.employeeNameAr}</strong><span>{text.deductionDescription}: {deductionDetail.deduction.description}</span><span>{text.originalAmount}: {deductionDetail.deduction.originalAmount}</span><span>{text.remainingAmount}: {deductionDetail.deduction.remainingAmount}</span></article><article><strong>{text.financialRecord}</strong>{deductionDetail.actions.length ? deductionDetail.actions.map((item) => <span key={item.id}>{item.businessDate} · {deductionActionLabel(text, item.actionType)} · {item.amount ?? "—"} · {item.plannedPayrollDate ?? item.reason ?? "—"}</span>) : <span>—</span>}</article></div> : null}</BaseerDialog>
    <BaseerDialog open={advanceOpen} title={text.addAdvance} language={language} busy={saving} onClose={() => setAdvanceOpen(false)} footer={<><BaseerButton type="button" variant="secondary" onClick={() => setAdvanceOpen(false)}>{text.cancel}</BaseerButton><BaseerButton type="submit" form="hr-advance-form" variant="primary" disabled={saving}>{text.save}</BaseerButton></>}><form id="hr-advance-form" className="administration-form" onSubmit={(event) => void saveAdvance(event)}><label>{text.selectEmployee}<BaseerSearchSelect required label={text.selectEmployee} value={advanceForm.employeeId} placeholder={text.selectEmployee} options={activeEmployees.map((item) => ({ id: item.id, label: `${item.employeeNumber} · ${language === "ar" ? item.nameAr : item.nameEn ?? item.nameAr}` }))} onChange={(employeeId) => setAdvanceForm((value) => ({ ...value, employeeId }))} /></label><label>{text.date}<input required type="date" value={advanceForm.businessDate} max={today()} onChange={(event) => setAdvanceForm((value) => ({ ...value, businessDate: event.target.value }))} /></label><label>{text.originalAmount}<input required inputMode="decimal" value={advanceForm.amount} onChange={(event) => setAdvanceForm((value) => ({ ...value, amount: event.target.value, allocations: value.allocations.map((allocation, index) => index === 0 ? { ...allocation, amount: event.target.value } : allocation) }))} /></label>{advanceForm.allocations.map((allocation, index) => <fieldset key={index}><legend>{text.selectVault}</legend><BaseerSearchSelect required label={text.selectVault} value={allocation.vaultId} placeholder={text.selectVault} options={activeVaults.map((item) => ({ id: item.id, label: language === "ar" ? item.nameAr : item.nameEn }))} onChange={(vaultId) => { const vault = activeVaults.find((item) => item.id === vaultId); setAdvanceForm((value) => ({ ...value, allocations: value.allocations.map((entry, entryIndex) => entryIndex === index ? { ...entry, vaultId, paymentMethod: vault?.paymentMethod ?? "" } : entry) })); }} /><input required inputMode="decimal" aria-label={text.amount} value={allocation.amount} onChange={(event) => setAdvanceForm((value) => ({ ...value, allocations: value.allocations.map((entry, entryIndex) => entryIndex === index ? { ...entry, amount: event.target.value } : entry) }))} /><BaseerSearchSelect searchable={false} label={language === "ar" ? "طريقة السداد" : "Payment method"} value={allocation.paymentMethod} placeholder={language === "ar" ? "طريقة السداد" : "Payment method"} options={(activeVaults.find((item) => item.id === allocation.vaultId)?.paymentMethods ?? []).map((method) => ({ id: method, label: method }))} onChange={(paymentMethod) => setAdvanceForm((value) => ({ ...value, allocations: value.allocations.map((entry, entryIndex) => entryIndex === index ? { ...entry, paymentMethod: paymentMethod as AdvanceAllocation["paymentMethod"] } : entry) }))} />{advanceForm.allocations.length > 1 ? <BaseerButton type="button" variant="quiet" onClick={() => setAdvanceForm((value) => ({ ...value, allocations: value.allocations.filter((_, entryIndex) => entryIndex !== index) }))}>×</BaseerButton> : null}</fieldset>)}<BaseerButton type="button" variant="quiet" onClick={() => setAdvanceForm((value) => ({ ...value, allocations: [...value.allocations, { vaultId: activeVaults[0]?.id ?? "", amount: "", paymentMethod: activeVaults[0]?.paymentMethod ?? "" }] }))}>+</BaseerButton><label>{text.notes}<textarea value={advanceForm.notes} onChange={(event) => setAdvanceForm((value) => ({ ...value, notes: event.target.value }))} /></label></form></BaseerDialog>
    <BaseerDialog open={settlementOpen} title={text.settleAdvance} language={language} busy={saving} onClose={() => setSettlementOpen(false)} footer={<><BaseerButton type="button" variant="secondary" onClick={() => setSettlementOpen(false)}>{text.cancel}</BaseerButton><BaseerButton type="submit" form="hr-advance-settlement-form" variant="primary" disabled={saving}>{text.save}</BaseerButton></>}><form id="hr-advance-settlement-form" className="administration-form" onSubmit={(event) => void saveSettlement(event)}><label>{text.date}<input required type="date" value={settlementForm.businessDate} max={today()} onChange={(event) => setSettlementForm((value) => ({ ...value, businessDate: event.target.value }))} /></label><label>{text.settlementAmount}<input required inputMode="decimal" value={settlementForm.amount} onChange={(event) => setSettlementForm((value) => ({ ...value, amount: event.target.value, allocations: value.allocations.map((allocation, index) => index === 0 ? { ...allocation, amount: event.target.value } : allocation) }))} /></label><label>{text.nextSettlementDate}<input type="date" min={settlementForm.businessDate} value={settlementForm.deferRemainingUntil} onChange={(event) => setSettlementForm((value) => ({ ...value, deferRemainingUntil: event.target.value }))} /></label>{settlementForm.allocations.map((allocation, index) => <fieldset key={index}><legend>{text.selectVault}</legend><BaseerSearchSelect required label={text.selectVault} value={allocation.vaultId} placeholder={text.selectVault} options={activeVaults.map((item) => ({ id: item.id, label: language === "ar" ? item.nameAr : item.nameEn }))} onChange={(vaultId) => { const vault = activeVaults.find((item) => item.id === vaultId); setSettlementForm((value) => ({ ...value, allocations: value.allocations.map((entry, entryIndex) => entryIndex === index ? { ...entry, vaultId, paymentMethod: vault?.paymentMethod ?? "" } : entry) })); }} /><input required inputMode="decimal" aria-label={text.amount} value={allocation.amount} onChange={(event) => setSettlementForm((value) => ({ ...value, allocations: value.allocations.map((entry, entryIndex) => entryIndex === index ? { ...entry, amount: event.target.value } : entry) }))} /><BaseerSearchSelect searchable={false} label={language === "ar" ? "طريقة السداد" : "Payment method"} value={allocation.paymentMethod} placeholder={language === "ar" ? "طريقة السداد" : "Payment method"} options={(activeVaults.find((item) => item.id === allocation.vaultId)?.paymentMethods ?? []).map((method) => ({ id: method, label: method }))} onChange={(paymentMethod) => setSettlementForm((value) => ({ ...value, allocations: value.allocations.map((entry, entryIndex) => entryIndex === index ? { ...entry, paymentMethod: paymentMethod as AdvanceAllocation["paymentMethod"] } : entry) }))} />{settlementForm.allocations.length > 1 ? <BaseerButton type="button" variant="quiet" onClick={() => setSettlementForm((value) => ({ ...value, allocations: value.allocations.filter((_, entryIndex) => entryIndex !== index) }))}>×</BaseerButton> : null}</fieldset>)}<BaseerButton type="button" variant="quiet" onClick={() => setSettlementForm((value) => ({ ...value, allocations: [...value.allocations, { vaultId: activeVaults[0]?.id ?? "", amount: "", paymentMethod: activeVaults[0]?.paymentMethod ?? "" }] }))}>+</BaseerButton><label>{text.notes}<textarea value={settlementForm.notes} onChange={(event) => setSettlementForm((value) => ({ ...value, notes: event.target.value }))} /></label></form></BaseerDialog>
    <BaseerDialog open={deferralOpen} title={text.deferAdvance} language={language} busy={saving} onClose={() => setDeferralOpen(false)} footer={<><BaseerButton type="button" variant="secondary" onClick={() => setDeferralOpen(false)}>{text.cancel}</BaseerButton><BaseerButton type="submit" form="hr-advance-deferral-form" variant="primary" disabled={saving}>{text.save}</BaseerButton></>}><form id="hr-advance-deferral-form" className="administration-form" onSubmit={(event) => void saveDeferral(event)}><label>{text.date}<input required type="date" value={deferralForm.businessDate} max={today()} onChange={(event) => setDeferralForm((value) => ({ ...value, businessDate: event.target.value }))} /></label><label>{text.nextSettlementDate}<input required type="date" min={deferralForm.businessDate} value={deferralForm.deferredUntil} onChange={(event) => setDeferralForm((value) => ({ ...value, deferredUntil: event.target.value }))} /></label><label>{text.deferralReason}<textarea required value={deferralForm.reason} onChange={(event) => setDeferralForm((value) => ({ ...value, reason: event.target.value }))} /></label></form></BaseerDialog>
    <BaseerDialog open={deductionOpen} title={text.addAdministrativeDeduction} language={language} busy={saving} onClose={() => setDeductionOpen(false)} footer={<><BaseerButton type="button" variant="secondary" onClick={() => setDeductionOpen(false)}>{text.cancel}</BaseerButton><BaseerButton type="submit" form="hr-administrative-deduction-form" variant="primary" disabled={saving}>{text.save}</BaseerButton></>}><form id="hr-administrative-deduction-form" className="administration-form" onSubmit={(event) => void saveDeduction(event)}><label>{text.selectEmployee}<BaseerSearchSelect required label={text.selectEmployee} value={deductionForm.employeeId} placeholder={text.selectEmployee} options={activeEmployees.map((item) => ({ id: item.id, label: `${item.employeeNumber} · ${language === "ar" ? item.nameAr : item.nameEn ?? item.nameAr}` }))} onChange={(employeeId) => setDeductionForm((value) => ({ ...value, employeeId }))} /></label><label>{text.date}<input required type="date" value={deductionForm.businessDate} max={today()} onChange={(event) => setDeductionForm((value) => ({ ...value, businessDate: event.target.value }))} /></label><label>{text.amount}<input required inputMode="decimal" value={deductionForm.amount} onChange={(event) => setDeductionForm((value) => ({ ...value, amount: event.target.value }))} /></label><label>{text.plannedPayrollDate}<input type="date" min={deductionForm.businessDate} value={deductionForm.plannedPayrollDate} onChange={(event) => setDeductionForm((value) => ({ ...value, plannedPayrollDate: event.target.value }))} /></label><label>{text.deductionDescription}<textarea required value={deductionForm.description} onChange={(event) => setDeductionForm((value) => ({ ...value, description: event.target.value }))} /></label></form></BaseerDialog>
    <BaseerDialog open={deductionDeferralOpen} title={text.deferDeduction} language={language} busy={saving} onClose={() => setDeductionDeferralOpen(false)} footer={<><BaseerButton type="button" variant="secondary" onClick={() => setDeductionDeferralOpen(false)}>{text.cancel}</BaseerButton><BaseerButton type="submit" form="hr-administrative-deduction-deferral-form" variant="primary" disabled={saving}>{text.save}</BaseerButton></>}><form id="hr-administrative-deduction-deferral-form" className="administration-form" onSubmit={(event) => void saveDeductionDeferral(event)}><label>{text.date}<input required type="date" value={deductionDeferralForm.businessDate} max={today()} onChange={(event) => setDeductionDeferralForm((value) => ({ ...value, businessDate: event.target.value }))} /></label><label>{text.plannedPayrollDate}<input required type="date" min={deductionDeferralForm.businessDate} value={deductionDeferralForm.deferredUntil} onChange={(event) => setDeductionDeferralForm((value) => ({ ...value, deferredUntil: event.target.value }))} /></label><label>{text.deferralReason}<textarea required value={deductionDeferralForm.reason} onChange={(event) => setDeductionDeferralForm((value) => ({ ...value, reason: event.target.value }))} /></label></form></BaseerDialog>
    <BaseerDialog open={deductionCancellationOpen} title={text.cancelDeduction} language={language} busy={saving} onClose={() => setDeductionCancellationOpen(false)} footer={<><BaseerButton type="button" variant="secondary" onClick={() => setDeductionCancellationOpen(false)}>{text.cancel}</BaseerButton><BaseerButton type="submit" form="hr-administrative-deduction-cancel-form" variant="primary" disabled={saving}>{text.save}</BaseerButton></>}><form id="hr-administrative-deduction-cancel-form" className="administration-form" onSubmit={(event) => void saveDeductionCancellation(event)}><label>{text.date}<input required type="date" value={deductionCancellationForm.businessDate} max={today()} onChange={(event) => setDeductionCancellationForm((value) => ({ ...value, businessDate: event.target.value }))} /></label><label>{text.deferralReason}<textarea required value={deductionCancellationForm.reason} onChange={(event) => setDeductionCancellationForm((value) => ({ ...value, reason: event.target.value }))} /></label></form></BaseerDialog>
  </BaseerWorkspace>;
}

function filter<T>(rows: readonly T[], value: string, fields: (row: T) => Array<string | null | undefined>) { const term = value.trim().toLowerCase(); return term ? rows.filter((row) => fields(row).filter(Boolean).join(" ").toLowerCase().includes(term)) : rows; }
function movementLabel(text: ReturnType<typeof hrText>, value: string) { return ({ SERVICE_COST: text.serviceCost, PAYROLL_ACCRUAL: text.payrollAccrual, PAYROLL_PAYMENT: text.payrollPayment, ADVANCE_ISSUED: text.advanceIssued, ADVANCE_SETTLEMENT: text.advanceSettlement })[value as "SERVICE_COST"] ?? value; }
function deductionIsOpen(value: HrAdministrativeDeduction) { return value.status === "OPEN" || value.status === "PARTIALLY_APPLIED" || value.status === "DEFERRED"; }
function deductionStatusLabel(text: ReturnType<typeof hrText>, value: HrAdministrativeDeduction["status"]) { return ({ OPEN: text.deductionOpen, PARTIALLY_APPLIED: text.deductionPartiallyApplied, APPLIED: text.deductionApplied, DEFERRED: text.deductionDeferredStatus, CANCELLED: text.cancelled })[value]; }
function deductionActionLabel(text: ReturnType<typeof hrText>, value: HrAdministrativeDeductionDetail["actions"][number]["actionType"]) { return ({ CREATED: text.addAdministrativeDeduction, DEFERRED: text.deferDeduction, CANCELLED: text.cancelDeduction, APPLIED: text.payrollPayment, REVERSED: text.cancelled })[value]; }
